SELECT 'contrato tablas de canecas_ventas (huella exacta)' AS verificacion, IF((SELECT COALESCE(MD5(GROUP_CONCAT(x ORDER BY BINARY x SEPARATOR '~~')), MD5('')) FROM (SELECT CONCAT_WS(0x1f, IFNULL(CAST(TABLE_NAME AS CHAR),'<NULL>'), IFNULL(CAST(TABLE_TYPE AS CHAR),'<NULL>'), IFNULL(CAST(ENGINE AS CHAR),'<NULL>'), IFNULL(CAST(TABLE_COLLATION AS CHAR),'<NULL>'), IFNULL(CAST(CREATE_OPTIONS AS CHAR),'<NULL>')) AS x FROM information_schema.TABLES WHERE TABLE_SCHEMA='u611730801_Plataforma' AND TABLE_NAME='canecas_ventas') h)='a3f41c203e25b2425b2de41762094cbb', 'OK', 'DETENER') AS resultado;
SELECT 'contrato columnas de canecas_ventas (huella exacta)' AS verificacion, IF((SELECT COALESCE(MD5(GROUP_CONCAT(x ORDER BY BINARY x SEPARATOR '~~')), MD5('')) FROM (SELECT CONCAT_WS(0x1f, IFNULL(CAST(TABLE_NAME AS CHAR),'<NULL>'), IFNULL(CAST(COLUMN_NAME AS CHAR),'<NULL>'), IFNULL(CAST(ORDINAL_POSITION AS CHAR),'<NULL>'), IFNULL(CAST(COLUMN_TYPE AS CHAR),'<NULL>'), IFNULL(CAST(IS_NULLABLE AS CHAR),'<NULL>'), IFNULL(CAST(COLUMN_DEFAULT AS CHAR),'<NULL>'), IFNULL(CAST(EXTRA AS CHAR),'<NULL>'), IFNULL(CAST(CHARACTER_SET_NAME AS CHAR),'<NULL>'), IFNULL(CAST(COLLATION_NAME AS CHAR),'<NULL>'), IFNULL(CAST(GENERATION_EXPRESSION AS CHAR),'<NULL>'), IFNULL(CAST(NUMERIC_PRECISION AS CHAR),'<NULL>'), IFNULL(CAST(NUMERIC_SCALE AS CHAR),'<NULL>'), IFNULL(CAST(DATETIME_PRECISION AS CHAR),'<NULL>'), IFNULL(CAST(CHARACTER_MAXIMUM_LENGTH AS CHAR),'<NULL>')) AS x FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='u611730801_Plataforma' AND TABLE_NAME='canecas_ventas') h)='89b9d793e6d0c8bf6298dcbc842df1d7', 'OK', 'DETENER') AS resultado;
SELECT 'contrato indices de canecas_ventas (huella exacta)' AS verificacion, IF((SELECT COALESCE(MD5(GROUP_CONCAT(x ORDER BY BINARY x SEPARATOR '~~')), MD5('')) FROM (SELECT CONCAT_WS(0x1f, IFNULL(CAST(TABLE_NAME AS CHAR),'<NULL>'), IFNULL(CAST(INDEX_NAME AS CHAR),'<NULL>'), IFNULL(CAST(NON_UNIQUE AS CHAR),'<NULL>'), IFNULL(CAST(SEQ_IN_INDEX AS CHAR),'<NULL>'), IFNULL(CAST(COLUMN_NAME AS CHAR),'<NULL>'), IFNULL(CAST(SUB_PART AS CHAR),'<NULL>'), IFNULL(CAST(INDEX_TYPE AS CHAR),'<NULL>'), IFNULL(CAST(COLLATION AS CHAR),'<NULL>'), IFNULL(CAST(NULLABLE AS CHAR),'<NULL>'), IFNULL(CAST(IGNORED AS CHAR),'<NULL>')) AS x FROM information_schema.STATISTICS WHERE TABLE_SCHEMA='u611730801_Plataforma' AND TABLE_NAME='canecas_ventas') h)='4eab5fb7a20cfb2a8ef9215b4d2eeb5e', 'OK', 'DETENER') AS resultado;
SELECT 'contrato foraneas de canecas_ventas (huella exacta)' AS verificacion, IF((SELECT COALESCE(MD5(GROUP_CONCAT(x ORDER BY BINARY x SEPARATOR '~~')), MD5('')) FROM (SELECT CONCAT_WS(0x1f, IFNULL(CAST(k.TABLE_NAME AS CHAR),'<NULL>'), IFNULL(CAST(k.CONSTRAINT_NAME AS CHAR),'<NULL>'), IFNULL(CAST(k.ORDINAL_POSITION AS CHAR),'<NULL>'), IFNULL(CAST(k.COLUMN_NAME AS CHAR),'<NULL>'), IFNULL(CAST(k.REFERENCED_TABLE_NAME AS CHAR),'<NULL>'), IFNULL(CAST(k.REFERENCED_COLUMN_NAME AS CHAR),'<NULL>'), IFNULL(CAST(r.UPDATE_RULE AS CHAR),'<NULL>'), IFNULL(CAST(r.DELETE_RULE AS CHAR),'<NULL>')) AS x FROM information_schema.KEY_COLUMN_USAGE k JOIN information_schema.REFERENTIAL_CONSTRAINTS r ON r.CONSTRAINT_SCHEMA=k.CONSTRAINT_SCHEMA AND r.TABLE_NAME=k.TABLE_NAME AND r.CONSTRAINT_NAME=k.CONSTRAINT_NAME WHERE k.TABLE_SCHEMA='u611730801_Plataforma' AND k.TABLE_NAME='canecas_ventas' AND k.REFERENCED_TABLE_NAME IS NOT NULL) h)='44ed3fb42937cc2902ccdda7fc9f4596', 'OK', 'DETENER') AS resultado;
SELECT 'contrato checks de canecas_ventas (huella exacta)' AS verificacion, IF((SELECT COALESCE(MD5(GROUP_CONCAT(x ORDER BY BINARY x SEPARATOR '~~')), MD5('')) FROM (SELECT CONCAT_WS(0x1f, IFNULL(CAST(t.TABLE_NAME AS CHAR),'<NULL>'), IFNULL(CAST(t.CONSTRAINT_NAME AS CHAR),'<NULL>'), IFNULL(CAST(c.CHECK_CLAUSE AS CHAR),'<NULL>')) AS x FROM information_schema.TABLE_CONSTRAINTS t JOIN information_schema.CHECK_CONSTRAINTS c ON c.CONSTRAINT_SCHEMA=t.CONSTRAINT_SCHEMA AND c.TABLE_NAME=t.TABLE_NAME AND c.CONSTRAINT_NAME=t.CONSTRAINT_NAME WHERE t.CONSTRAINT_SCHEMA='u611730801_Plataforma' AND t.TABLE_NAME='canecas_ventas') h)='4c8db200a4327db0a42c31cfb81d5e36', 'OK', 'DETENER') AS resultado;
SELECT 'ventas historicas sin direccion (no se inventan datos)' AS verificacion, IF((SELECT COUNT(*) FROM `u611730801_Plataforma`.canecas_ventas WHERE direccion_entrega IS NOT NULL)=0, 'OK', 'DETENER') AS resultado;
